//! Small, dependency-free integer arithmetic helpers.
//!
//! The crate offers two flavours of the same operation:
//!
//! * [`add`] — the plain, infallible version that panics on overflow in
//!   debug builds.
//! * [`checked_add`] — the fallible version, returning [`None`] instead of
//!   panicking or wrapping.
//!
//! Prefer [`checked_add`] at trust boundaries (parsing, user input, wire
//! formats) where an overflow must be reported rather than abort the process.
//!
//! # Examples
//!
//! ```
//! assert_eq!(target_lib::add(2, 3), 5);
//! assert_eq!(target_lib::checked_add(i32::MAX, 1), None);
//! ```
//!
//! The crate is `no_std` compatible: it uses only `core` and allocates nothing.

#![no_std]
#![forbid(unsafe_code)]
#![warn(missing_docs, rust_2018_idioms)]

/// Returns the sum of `a` and `b`.
///
/// # Panics
///
/// Panics with `attempt to add with overflow` when debug assertions are
/// enabled (the default for `cargo test` and `cargo run`). In release builds
/// the same inputs wrap around in two's complement instead. Use
/// [`checked_add`] when overflow must be handled explicitly.
///
/// # Examples
///
/// ```
/// assert_eq!(target_lib::add(2, 3), 5);
/// assert_eq!(target_lib::add(-2, 3), 1);
/// assert_eq!(target_lib::add(0, 0), 0);
/// ```
#[must_use]
#[inline]
pub fn add(a: i32, b: i32) -> i32 {
    a + b
}

/// Returns the sum of `a` and `b`, or [`None`] if the result would overflow.
///
/// # Examples
///
/// ```
/// assert_eq!(target_lib::checked_add(2, 3), Some(5));
/// assert_eq!(target_lib::checked_add(i32::MAX, 1), None);
/// assert_eq!(target_lib::checked_add(i32::MIN, -1), None);
/// ```
#[must_use]
#[inline]
pub fn checked_add(a: i32, b: i32) -> Option<i32> {
    a.checked_add(b)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn add_returns_the_sum() {
        assert_eq!(add(2, 3), 5);
        assert_eq!(add(-2, -3), -5);
        assert_eq!(add(-2, 3), 1);
        assert_eq!(add(2, -3), -1);
    }

    #[test]
    fn add_has_a_neutral_element() {
        for value in [i32::MIN, -1, 0, 1, i32::MAX] {
            assert_eq!(add(value, 0), value, "value = {value}");
            assert_eq!(add(0, value), value, "value = {value}");
        }
    }

    #[test]
    fn add_is_commutative() {
        let samples = [-1000, -7, -1, 0, 1, 7, 1000];
        for a in samples {
            for b in samples {
                assert_eq!(add(a, b), add(b, a), "a = {a}, b = {b}");
            }
        }
    }

    #[test]
    fn checked_add_reports_overflow_at_both_bounds() {
        assert_eq!(checked_add(i32::MAX, 1), None);
        assert_eq!(checked_add(i32::MIN, -1), None);
        assert_eq!(checked_add(i32::MAX, i32::MAX), None);
        assert_eq!(checked_add(i32::MIN, i32::MIN), None);
    }

    #[test]
    fn checked_add_accepts_the_exact_bounds() {
        assert_eq!(checked_add(i32::MAX, 0), Some(i32::MAX));
        assert_eq!(checked_add(i32::MIN, 0), Some(i32::MIN));
        assert_eq!(checked_add(0, i32::MAX), Some(i32::MAX));
        assert_eq!(checked_add(i32::MIN, i32::MAX), Some(-1));
    }

    /// The two entry points must agree on every input that does not overflow,
    /// so callers can migrate between them without changing behaviour.
    #[test]
    fn checked_add_agrees_with_add_when_in_range() {
        let samples = [-1000, -7, -1, 0, 1, 7, 1000];
        for a in samples {
            for b in samples {
                assert_eq!(
                    checked_add(a, b),
                    Some(add(a, b)),
                    "a = {a}, b = {b}"
                );
            }
        }
    }

    /// Overflow panics only exist while debug assertions are on, so this test
    /// is compiled out in release builds (`cargo test --release`).
    #[cfg(debug_assertions)]
    #[test]
    #[should_panic(expected = "attempt to add with overflow")]
    fn add_panics_on_overflow_in_debug_builds() {
        let _ = add(i32::MAX, 1);
    }
}

